from wcommon import dims_G, dims_M, legend, notes, head, sched
from wmodel import G, M
LAYER = "M-HVAC"
ROWS=[(lambda s,x,y: s.duct([(x-0.35,y),(x+0.35,y)],w=0.16), "دكت هواء مكشوف مجلفن معزول مدهون أسود مطفي", "exposed insulated duct, matte black"),
      (lambda s,x,y: s.diffuser(x,y,0.25), "مخرج هواء شريحي (Linear slot) جانبي أسود", "linear slot diffuser"),
      (lambda s,x,y: s.grille(x,y,0.35,0.16), "مخرج هواء راجع", "return air grille"),
      (lambda s,x,y: s.cassette(x,y,0.4), "وحدة كاسيت سقفية 4 اتجاهات", "4-way cassette unit"),
      (lambda s,x,y: s.rect(x-0.35,y-0.12,x+0.35,y+0.12,color=6), "وحدة داخلية مخفية (ducted) فوق السقف", "concealed ducted indoor unit"),
      (lambda s,x,y: s.split_unit(x,y,0.5,0.14), "وحدة سبليت جدارية", "wall split unit")]
def _unit(s,r,t):
    s.rect(*r,color=6,lw=35); s.hatch([(r[0],r[1]),(r[2],r[1]),(r[2],r[3]),(r[0],r[3])],pattern="ANSI31",scale=0.3,color=6); s.label((r[0]+r[2])/2,(r[1]+r[3])/2,t,h=0.1,color=7)
def draw_G(s):
    _unit(s,(9.4,42.55,10.9,43.45),"DSU-1\n5 TR مخفية")
    pts=[(10.9,43.0),(14.05,43.0),(14.05,39.6)]
    s.duct(pts,w=0.5,diffusers=[(12.5,43.0),(14.05,42.3),(14.05,41.2),(14.05,40.1)],label="دكت تغذية 500×300 مكشوف أسود")
    s.grille(10.2,42.2,0.6,0.25); s.text(10.2,41.95,"راجع 600×250",h=0.09,attach=2)
    s.text(14.5,39.5,"نهاية الدكت عند كرسي الانتظار",h=0.09)
    s.cassette(11.85,52.4,0.84); s.text(11.85,51.85,"CU-1 كاسيت 2 TR - التحضير",h=0.1,attach=2)
    s.pline([(9.65,49.5),(9.65,43.5),(9.9,43.5)],color=6,lw=13,linetype="DASHED"); s.pline([(9.65,49.5),(9.65,52.4),(11.4,52.4)],color=6,lw=13,linetype="DASHED")
    s.rect(9.4,49.3,9.9,49.8,color=6); s.text(9.0,49.9,"مواسير فريون إلى السطح (منور)",h=0.09,attach=3)
    s.dim((10.9,43.0),(14.05,43.0),offset=0.9); s.dim((14.05,43.0),(14.05,39.6),offset=1.4,horizontal=False); s.dim((14.05,39.6),(14.4,39.6),offset=-0.8)
    s.dim((14.05,42.3),(14.05,41.2),offset=0.6,horizontal=False); s.dim((14.05,41.2),(14.05,40.1),offset=0.6,horizontal=False)
    dims_G(s,[(11.85,52.4),(10.15,43.0)])
    legend(s,"G","رموز التكييف - HVAC LEGEND",ROWS)
    sched(s,"G","جدول وحدات التكييف - الأرضي",["الوحدة","المواصفة / المكان","القدرة"],[("DSU-1","وحدة مخفية Ducted فوق مدخل المطبخ تخدم الصالة والمدخل","5 طن (60,000 BTU)"),("CU-1","كاسيت سقفي 4 اتجاهات بمنطقة التحضير","2 طن (24,000 BTU)"),
        ("دكت تغذية","500×300 مم مجلفن معزول 25 مم مكشوف أسود","6.6 م"),("مخارج","شريحي خطي 1200×150 أسود","4"),("راجع","600×250 مع فلتر","1"),("وحدات خارجية","على السطح عبر منور الخدمات","2"),("المطبخ","تهوية ميكانيكية فقط (مخطط الشفاط) + هواء تعويض","-"),("المجموع","","7 طن")])
    notes(s,"G",["الدكت يبدأ من الوحدة المخفية عند جدار المطبخ الأيسر، يعبر الصالة إلى الجدار الأيمن ثم يمتد على حافة الجدار الأيمن حتى كرسي الانتظار (حسب التصميم).",
        "الدكت مكشوف بالسقف الأسود ويدهن أسود مطفي، المخارج الشريحية على جانب الدكت باتجاه الصالة.","الوحدات إنفرتر R410A/R32، تصريف مياه التكثيف إلى أقرب بلوعة بميول 1%.","الأبعاد الحمراء: مسار الدكت وأطواله والمسافات بين المخارج ومواقع الوحدات."],"ملاحظات التكييف")
    head(s,"G","مخطط التكييف - الدور الأرضي: وحدة مخفية 5 طن بدكت مكشوف من الجدار الأيسر إلى الأيمن ثم على حافته حتى كرسي الانتظار، وكاسيت 2 طن بالتحضير.")
def draw_M(s):
    _unit(s,(3.7,23.35,6.3,24.85),"DSU-2 5 TR مخفية\nفوق سقف الممر")
    pts=[(0.6,17.2),(0.6,23.4),(8.3,23.4),(8.3,17.2)]
    s.duct(pts,w=0.5,diffusers=[(0.6,18.6),(0.6,20.5),(0.6,22.3),(2.0,23.4),(7.0,23.4),(8.3,18.6),(8.3,20.5),(8.3,22.3)],label="دكت تغذية 500×300 مكشوف أسود - على محيط الجدران")
    s.grille(5.0,24.95,0.7,0.25); s.text(5.0,25.15,"راجع 700×250",h=0.09,attach=2)
    for p,t in [((15.4,18.8),"CU-2 1.5 TR"),((19.9,18.8),"CU-3 2 TR"),((18.0,14.6),"CU-4 2 TR"),((11.5,23.3),"CU-5 1.5 TR"),((18.5,23.3),"CU-6 1.5 TR")]:
        s.cassette(*p,0.84); s.text(p[0],p[1]-0.55,t,h=0.1,attach=2)
    s.split_unit(22.1,21.6,0.9,0.25); s.text(21.9,21.2,"SP-1 سبليت 1.5 TR سيرفر 24/7",h=0.09,attach=3)
    s.rect(0.15,23.4,0.95,24.9,color=6); s.label(0.55,24.15,"منور\nفريون",h=0.09,color=7)
    s.dim((0.6,17.2),(0.6,23.4),offset=-1.9,horizontal=False); s.dim((0.6,23.4),(8.3,23.4),offset=0.5); s.dim((8.3,23.4),(8.3,17.2),offset=0.5,horizontal=False)
    s.dim((0.1,17.2),(0.6,17.2),offset=-0.4); s.dim((8.3,17.2),(8.7,17.2),offset=-0.4)
    s.dim((0.6,18.6),(0.6,20.5),offset=0.6,horizontal=False); s.dim((0.6,20.5),(0.6,22.3),offset=0.6,horizontal=False)
    dims_M(s,[(15.4,18.8),(19.9,18.8),(18.0,14.6),(11.5,23.3),(18.5,23.3)])
    legend(s,"M","رموز التكييف - LEGEND",ROWS)
    sched(s,"M","وحدات التكييف - الميزانين",["الوحدة","المكان","القدرة"],[("DSU-2","مخفية بالممر تخدم الجلسات والبار","5 طن"),("CU-2","المدير التنفيذي","1.5"),("CU-3","مكتب المدير","2"),("CU-4","الاجتماعات","2"),("CU-5/6","المكاتب المفتوحة","1.5×2"),("SP-1","السيرفر","1.5"),("دكت","500×300 مكشوف","21.6 م"),("مخارج","شريحي أسود","8"),("المجموع","","15 طن")])
    notes(s,"M",["ارتفاع السقف 2.90 م لذلك الدكت مكشوف على محيط الجدران: يبدأ من الجدار الأيسر فوق كنب الجلسات، يتجه للخلف نحو الحمامات ويتبع انكسار الجدار ثم يعود على الجدار الأيمن فوق الجلسات كاملة.",
        "أسفل الدكت 2.40 م، يدهن أسود مطفي مع تعليق بأشاير مجلفنة كل 1.5 م.","الأبعاد الحمراء: مسار الدكت ومسافات المخارج ومواقع الكاسيت."],"ملاحظات")
    head(s,"M","مخطط التكييف - الميزانين: وحدة مخفية 5 طن بدكت مكشوف على محيط الجلسات (يسار - خلف - يمين)، كاسيت للمكاتب وسبليت للسيرفر.")
